ALTER TABLE "system_model_usage" DROP CONSTRAINT "system_model_usage_call_shape";--> statement-breakpoint
ALTER TABLE "system_model_usage" ADD CONSTRAINT "system_model_usage_call_shape" CHECK ("system_model_usage"."call_count" BETWEEN 0 AND 4 AND "system_model_usage"."unknown_call_count" BETWEEN 0 AND "system_model_usage"."call_count" AND (("system_model_usage"."outcome" = 'budget_exhausted') = ("system_model_usage"."call_count" = 0)) AND ("system_model_usage"."purpose" <> 'public_sample_spin' OR "system_model_usage"."call_count" <= 3) AND ("system_model_usage"."outcome" <> 'succeeded' OR (("system_model_usage"."purpose" = 'trend_autopsy' AND "system_model_usage"."cost_state" = 'measured' AND "system_model_usage"."call_count" = 4) OR ("system_model_usage"."purpose" = 'public_sample_spin' AND "system_model_usage"."call_count" BETWEEN 2 AND 3))) AND (("system_model_usage"."cost_state" = 'unknown') = ("system_model_usage"."unknown_call_count" > 0)));